def handle(args, state, ds):
    st = ds.sync_status()
    if not st.get("drift"):
        return {"status": "synced", "detail": st.get("detail", "all linked accounts up to date")}
    return {"status": "syncing", "detail": st.get("detail", "accounts still updating")}

def handle(args, state, ds):
    rep = ds.consistency_report()
    if rep.get("pending", 0) == 0:
        return {"status": "complete", "remaining": 0}
    return {"status": "in_progress", "remaining": rep.get("pending", 0)}

